// Coucou plugin for OpenCode — generated by Coucou.
// OpenCode V2 approvals require an explicit human click; V1 remains display-only.
import { spawn } from 'node:child_process';
export const COUCOU_PLUGIN_REVISION = 8;
export const COUCOU_PATCH_PREVIEW_REVISION = 1;

const HOOK = {HOOK};
const EVENTS = {
  'session.created': 'SessionStart',
  'session.error': 'StopFailure',
  'session.deleted': 'SessionEnd',
  'session.execution.succeeded': 'Stop',
};

// Only OpenCode's native execution-success event means finished. Idle status
// and intermediate model/tool endings are not completion signals.
function lifecycleEvent(type) {
  return EVENTS[type];
}

export function sameDirectory(left, right, windows = process.platform === 'win32') {
  const normalize = (value) => {
    const path = String(value || '').replace(/\\/g, '/').replace(/\/+$/, '');
    return windows ? path.toLowerCase() : path;
  };
  return normalize(left) === normalize(right);
}

// Display-only: adapt completed FileDiff.Info results to the existing viewer.
// Never read files or forward raw tool inputs (which may contain secrets).
export function patchPreviews(event) {
  if (event?.status !== 'completed' || event.tool !== 'patch') return [];
  const metadata = event.result?.metadata;
  if (!Array.isArray(metadata?.files) || metadata.truncated === true) return [];
  const bytes = (text) => new TextEncoder().encode(text).length;
  const previews = [];
  let budget = 256 * 1024;
  for (const file of metadata.files.slice(0, 4)) {
    if (!file || typeof file.file !== 'string' || !file.file ||
        /[\u0000-\u001f\u007f]/.test(file.file) || bytes(file.file) > 2000) continue;
    const name = file.file.replace(/\\/g, '/').split('/').pop().toLowerCase();
    if ((name.startsWith('.env') && !['.env.example', '.env.sample', '.env.template'].includes(name)) ||
        /^(?:auth|credentials|service[-_]account)(?:[.-].*)?\.jsonc?$/.test(name) ||
        /^id_(?:rsa|dsa|ecdsa|ed25519)$/.test(name) || /\.(?:pem|key|p12|pfx|kdbx)$/.test(name)) continue;
    if (!['added', 'deleted', 'modified'].includes(file.status) || typeof file.patch !== 'string' ||
        file.patch.length > 200 * 1024 || bytes(file.patch) > 200 * 1024 ||
        !Number.isSafeInteger(file.additions) || file.additions < 0 ||
        !Number.isSafeInteger(file.deletions) || file.deletions < 0) continue;
    const parsed = patchHunks(file.patch);
    if (!parsed || parsed.added !== file.additions || parsed.removed !== file.deletions) continue;
    const edits = parsed.hunks.map((h) => ({ old_string: h.old, new_string: h.new }));
    if (edits.every((e) => e.old_string.replace(/\n$/, '') === e.new_string.replace(/\n$/, ''))) continue;
    let preview;
    if (file.status === 'added') {
      if (edits.length !== 1 || parsed.removed || edits[0].old_string || parsed.hunks[0].newStart !== 1) continue;
      preview = { tool_name: 'Write', tool_input: { file_path: file.file, content: edits[0].new_string } };
    } else {
      if (file.status === 'deleted' && (edits.length !== 1 || parsed.added || edits[0].new_string || parsed.hunks[0].oldStart !== 1)) continue;
      preview = edits.length === 1
        ? { tool_name: 'Edit', tool_input: { file_path: file.file, ...edits[0] } }
        : { tool_name: 'MultiEdit', tool_input: { file_path: file.file, edits } };
    }
    const size = bytes(JSON.stringify(preview));
    if (size > 200 * 1024 || size + 4096 > budget) continue;
    budget -= size + 4096;
    previews.push(preview);
  }
  return previews;
}

// Decode each unified hunk separately. Gaps are not invented or read back.
function patchHunks(patch) {
  const lines = patch.replace(/\r\n/g, '\n').split('\n');
  if (lines.length > 8000) return null;
  if (lines.at(-1) === '') lines.pop();
  const hunks = [];
  let current;
  let added = 0, removed = 0, total = 0;
  const finish = () => {
    if (!current || current.old.length !== current.oldCount || current.new.length !== current.newCount) return false;
    hunks.push({ oldStart: current.oldStart, newStart: current.newStart,
      old: current.old.join('\n') + (current.old.length && !current.oldNoNewline ? '\n' : ''),
      new: current.new.join('\n') + (current.new.length && !current.newNoNewline ? '\n' : '') });
    return true;
  };
  for (const line of lines) {
    const header = /^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@(?: .*)?$/.exec(line);
    if (header) {
      if ((current && !finish()) || hunks.length >= 64) return null;
      const [oldStart, oldCount, newStart, newCount] = [Number(header[1]), Number(header[2] ?? 1), Number(header[3]), Number(header[4] ?? 1)];
      if (![oldStart, oldCount, newStart, newCount].every(Number.isSafeInteger) ||
          oldCount + newCount > 4000 || oldCount * newCount > 1_000_000 ||
          (oldCount && !oldStart) || (newCount && !newStart) ||
          (current && (oldStart < current.oldStart + current.oldCount || newStart < current.newStart + current.newCount))) return null;
      current = { oldStart, oldCount, newStart, newCount, old: [], new: [], last: null };
      continue;
    }
    if (!current) continue; // File headers; metadata supplies the path.
    if (line === '\\ No newline at end of file') {
      if (!current.last) return null;
      if (current.last !== '+') current.oldNoNewline = true;
      if (current.last !== '-') current.newNoNewline = true;
      current.last = null;
      continue;
    }
    const kind = line[0];
    if (![' ', '-', '+'].includes(kind)) return null;
    if (kind !== '+') {
      if (current.oldNoNewline) return null;
      current.old.push(line.slice(1)); total++;
    }
    if (kind !== '-') {
      if (current.newNoNewline) return null;
      current.new.push(line.slice(1)); total++;
    }
    if (total > 4000 || current.old.length > current.oldCount || current.new.length > current.newCount) return null;
    if (kind === '+') added++;
    if (kind === '-') removed++;
    current.last = kind;
  }
  return finish() ? { hunks, added, removed } : null;
}

// Unsupported/conditional forms stay in OpenCode rather than losing semantics.
export function questionForm(form) {
  if (!Array.isArray(form.fields) || !form.fields.length) return null;
  const questions = [];
  const mappings = [];
  const keys = new Set();
  for (const field of form.fields) {
    if (typeof field.key !== 'string' || keys.has(field.key) || field.hidden || field.when?.length) return null;
    keys.add(field.key);
    if (!['string', 'boolean', 'multiselect'].includes(field.type)) return null;
    const options = field.type === 'boolean'
      ? [{ label: 'Yes', value: true }, { label: 'No', value: false }]
      : (field.options || []);
    if (options.some((o) => typeof o.label !== 'string' || !o.label)) return null;
    if (new Set(options.map((o) => o.label)).size !== options.length) return null;
    // OpenCode question forms put the short header in title and the actual
    // question in description. Field keys stay internal in the answer mapping.
    const question = [field.description, field.title, field.key]
      .find((value) => typeof value === 'string' && value.trim());
    // The relay answers by question text. Ambiguous duplicate text stays in
    // OpenCode rather than adding implementation IDs to the visible question.
    if (!question || questions.some((item) => item.question === question)) return null;
    const custom = field.type === 'string' && (!options.length || field.custom === true);
    if (!options.length && !custom) return null;
    questions.push({ question, multiSelect: field.type === 'multiselect', custom,
      options: options.map((o) => ({ label: o.label, description: o.description || '' })) });
    mappings.push({ field, question, options, custom });
  }
  // The relay caps individual strings at 2,000 UTF-8 bytes, not the whole
  // form at 1,800 characters. Several ordinary questions can exceed the old
  // aggregate cap even though every question and option fits losslessly.
  const bytes = (text) => new TextEncoder().encode(text).length;
  for (const q of questions) {
    if (bytes(q.question) > 2000 || q.options.some((o) => bytes(o.label) > 2000 || bytes(o.description) > 2000)) return null;
  }
  const input = { questions };
  if (bytes(JSON.stringify(input)) > 64 * 1024) return null;
  return {
    input,
    answer(answers) {
      if (!answers || Object.keys(answers).length !== mappings.length) return null;
      const result = Object.create(null);
      for (const { field, question, options, custom } of mappings) {
        const pick = answers[question];
        const map = (label) => options.find((o) => o.label === label);
        if (field.type === 'multiselect') {
          if (!Array.isArray(pick) || !pick.length || new Set(pick).size !== pick.length || pick.some((p) => !map(p))) return null;
          result[field.key] = pick.map((p) => map(p).value);
        } else {
          if (typeof pick !== 'string') return null;
          const option = map(pick);
          if (!option && !custom) return null;
          result[field.key] = option ? option.value : pick;
        }
      }
      return result;
    },
  };
}

// Retain the existing V1 entrypoint without changing its approval behavior.
export const CoucouPlugin = async ({ directory } = {}) => {
  const forward = (event, fields) => {
    try {
      const child = spawn(HOOK, ['--agent', 'opencode'], { stdio: ['pipe', 'ignore', 'ignore'], windowsHide: true });
      const timer = setTimeout(() => child.kill(), 3000);
      timer.unref();
      child.on('error', () => {});
      child.once('close', () => clearTimeout(timer));
      child.stdin.on('error', () => {});
      child.stdin.end(JSON.stringify({ hook_event_name: event, cwd: directory || '', ...fields }) + '\n');
      child.unref();
    } catch {}
  };
  return {
    event: async ({ event }) => {
      const name = lifecycleEvent(event?.type);
      const id = event?.properties?.sessionID || event?.properties?.info?.id;
      if (name && id) forward(name, { session_id: id });
    },
    'tool.execute.before': async (e) => forward('PreToolUse', { session_id: e.sessionID, tool_name: e.tool }),
    'tool.execute.after': async (e) => forward('PostToolUse', { session_id: e.sessionID, tool_name: e.tool }),
  };
};

export default {
  id: 'coucou',
  server: CoucouPlugin,
  async setup(ctx) {
    const children = new Set();
    const controller = new AbortController();
    const registrations = [];
    let closed = false;
    const forms = new Map();
    const directories = new Map();
    let clientPromise;
    function formClient() {
      // Form operations belong to the full client, not the plugin's SessionDomain.
      // Discover only the existing local service; never start another server.
      clientPromise ??= (async () => {
        const { OpenCode, Service } = await import('../coucou-sdk/client.mjs');
        const endpoint = await Service.discover();
        if (!endpoint) return null;
        return OpenCode.make({ baseUrl: endpoint.url, headers: Service.headers(endpoint) });
      })().catch(() => {
        console.warn('[coucou] Question connection unavailable; native OpenCode questions remain active. Reinstall the Coucou OpenCode integration to restore its bundled client.');
        return null;
      });
      return clientPromise;
    }

    function relay(event, fields, decision = false, signal) {
      if (closed || children.size >= 16) return Promise.resolve(null);
      return new Promise((resolve) => {
        let child;
        let output = '';
        let settled = false;
        let timer;
        const finish = (value = null) => {
          if (settled) return;
          settled = true;
          clearTimeout(timer);
          signal?.removeEventListener('abort', cancel);
          if (child) { children.delete(child); child.kill(); }
          resolve(value);
        };
        const cancel = () => finish();
        if (signal?.aborted) return finish();
        signal?.addEventListener('abort', cancel, { once: true });
        try {
          child = spawn(HOOK, ['--agent', 'opencode'], {
            stdio: ['pipe', decision ? 'pipe' : 'ignore', 'ignore'],
            windowsHide: true,
          });
          children.add(child);
          timer = setTimeout(() => finish(), decision ? 115_000 : 3000);
          timer.unref();
          child.on('error', () => finish());
          child.stdin.on('error', () => finish());
          child.stdout?.on('data', (data) => {
            output += data.toString();
            if (output.length > 65_536) finish();
          });
          child.once('close', (code) => {
            if (code !== 0) return finish();
            if (!decision) return finish(true);
            try {
              const result = JSON.parse(output).hookSpecificOutput;
              if (result?.hookEventName !== 'PermissionRequest') return finish();
              const behavior = result.decision?.behavior;
              finish(behavior === 'allow' || behavior === 'deny' ? result.decision : null);
            } catch { finish(); }
          });
          child.stdin.end(JSON.stringify({ hook_event_name: event, ...fields }) + '\n');
        } catch { finish(); }
      });
    }

    async function fields(sessionID) {
      if (!directories.has(sessionID)) {
        if (directories.size >= 128) directories.delete(directories.keys().next().value);
        directories.set(sessionID, ctx.session.get({ sessionID }, { signal: AbortSignal.timeout(2000) })
          .then((session) => session.location.directory)
          .catch(() => ctx.location.directory));
      }
      const cwd = await directories.get(sessionID);
      return { session_id: sessionID, cwd };
    }

    try {
      registrations.push(await ctx.session.hook('prompt', async (e) => {
        void relay('UserPromptSubmit', await fields(e.sessionID));
      }));
      registrations.push(await ctx.tool.hook('execute.before', async (e) => {
        void relay('PreToolUse', { ...await fields(e.sessionID), tool_name: e.tool });
      }));
      registrations.push(await ctx.tool.hook('execute.after', async (e) => {
        const common = await fields(e.sessionID);
        let previews = [];
        try { previews = patchPreviews(e); } catch { /* Preview failures must not fail a tool. */ }
        if (previews.length) {
          // Bounded by the existing relay deadline; completion cannot overtake the final edit.
          await Promise.all(previews.map((preview) => relay('PostToolUse', { ...common, ...preview })));
          return;
        }
        void relay(e.status === 'error' ? 'PostToolUseFailure' : 'PostToolUse', {
          ...common, tool_name: e.tool,
        });
      }));
      registrations.push(await ctx.permission.hook('evaluate', async (e) => {
        // Never override configured allows or denies, and never remember approvals.
        if (e.effect !== 'ask' || e.resources.join('\n').length > 1800) return;
        const answer = await relay('PermissionRequest', {
          ...await fields(e.sessionID),
          tool_name: e.action,
          tool_input: { command: e.resources.join('\n') },
        }, true);
        if (answer?.behavior === 'allow' || answer?.behavior === 'deny') e.effect = answer.behavior;
        // Timeout, disconnect, malformed output: keep 'ask' for the native UI.
      }));
    } catch (error) {
      closed = true;
      for (const child of children) child.kill();
      await Promise.allSettled(registrations.map((r) => r.dispose()));
      throw error;
    }

    async function showForm(form) {
      const client = await formClient();
      if (closed || !client || forms.has(form.id) || forms.size >= 8) return;
      const converted = questionForm(form);
      if (!converted) return;
      const pending = new AbortController();
      forms.set(form.id, pending);
      try {
        const response = await relay('PermissionRequest', {
          ...await fields(form.sessionID), tool_name: 'AskUserQuestion', tool_input: converted.input,
          coucou_source_id: form.id,
        }, true, pending.signal);
        const answer = converted.answer(response?.updatedInput?.answers);
        if (!answer || closed) return;
        const input = { sessionID: form.sessionID, formID: form.id };
        const current = await client.session.form.get(input, { signal: AbortSignal.timeout(3000) });
        if (current.state.status !== 'pending' || JSON.stringify(current.fields) !== JSON.stringify(form.fields)) return;
        await client.session.form.reply({ ...input, answer }, { signal: AbortSignal.timeout(3000) });
      } catch {
        // Native form remains available on a failed or stale response.
      } finally {
        forms.delete(form.id);
        // A declined duplicate relay is not a cancelled OpenCode form. Only
        // form.replied/form.cancelled may close another instance's active card.
      }
    }

    // Consume events without waiting on relay I/O; reconnect with bounded backoff.
    let warnedDisconnected = false;
    const events = (async () => {
      while (!closed) {
        try {
          for await (const e of ctx.event.subscribe({ signal: controller.signal })) {
            warnedDisconnected = false;
            if (e.location?.directory && !sameDirectory(e.location.directory, ctx.location.directory)) continue;
            if (e.type === 'session.moved' || e.type === 'session.deleted') directories.delete(e.data?.sessionID);
            if (e.type === 'server.connected') {
              clientPromise = undefined;
              void formClient().then((client) => client?.form.list({ location: { directory: ctx.location.directory } }, { signal: controller.signal }))
                .then((pending) => {
                  if (!closed && pending) for (const form of pending.data.slice(0, 8)) void showForm(form);
                }).catch(() => {});
            }
            if (e.type === 'form.created') void showForm(e.data.form);
            if (e.type === 'form.replied' || e.type === 'form.cancelled') {
              forms.get(e.data.id)?.abort();
              void fields(e.data.sessionID).then((f) => relay('OpenCodeFormClosed', {
                ...f, coucou_source_id: e.data.id,
              })).catch(() => {});
            }
            const name = lifecycleEvent(e.type);
            const id = e.data?.sessionID;
            if (name && id) void fields(id).then((f) => relay(name, {
              ...f, ...(typeof e.id === 'string' ? { coucou_event_id: e.id } : {}),
            })).then((delivered) => {
              if (name === 'Stop' && delivered !== true && !closed) {
                console.warn('[coucou] Native completion relay failed; Coucou may not show this finished task.');
              }
            }).catch(() => {
              if (!closed) console.warn('[coucou] Lifecycle event could not be forwarded.');
            });
          }
        } catch {
          if (!closed && !warnedDisconnected) {
            warnedDisconnected = true;
            console.warn('[coucou] Event stream disconnected; reconnecting. Events during the interruption may be missed.');
          }
        }
        if (!closed) await new Promise((resolve) => {
          const done = () => {
            clearTimeout(timer);
            controller.signal.removeEventListener('abort', done);
            resolve();
          };
          const timer = setTimeout(done, 2000);
          controller.signal.addEventListener('abort', done, { once: true });
          if (controller.signal.aborted) done();
        });
      }
    })();
    return async () => {
      closed = true;
      controller.abort();
      for (const child of children) child.kill();
      await Promise.allSettled([...registrations.map((r) => r.dispose()), events]);
    };
  },
};
